// --- Sparse-CBOR write (ADR-0042 driver path). ---

// Marshal writes the SoA buffer to w as the sparse-CBOR wire
// format produced through factsschema/dml_cbor. Thin wrapper
// around AppStateReplyBuildEntities — the per-row chain lives there and
// works against any leeway-DML class that structurally satisfies
// AppStateReplyEntityI.
func (c *AppStateReplyColumns) Marshal(w io.Writer) (err error) {
	ent := appStateReplyPool.Get().(*cbdml.InEntityFacts)
	defer appStateReplyPool.Put(ent)
	ent.SetActiveSections(AppStateReplyActiveSections)
	ent.Builder().SetActiveFields(AppStateReplyActiveFields())
	err = AppStateReplyBuildEntities(ent, c)
	if err != nil {
		return
	}
	var recs []*arrowrowcbor.Record
	recs, err = ent.TransferRecords(nil)
	if err != nil {
		err = eh.Errorf("appstatereply: transfer records: %w", err)
		return
	}
	rb := arrowrowcbor.JoinRecords(recs)
	_, err = w.Write(rb)
	if err != nil {
		err = eh.Errorf("appstatereply: marshal write: %w", err)
	}
	return
}

// --- Read path (ra-based). ---

// appStateReplyReader composes the readaccess helpers this kind needs.
// Constructed per Unmarshal call; released via defer.
type appStateReplyReader struct {
	EntityId        *ra.ReadAccessFactsPlainEntityIdAttributes
	EntityTimestamp *ra.ReadAccessFactsPlainEntityTimestampAttributes
	Bool            *ra.ReadAccessFactsTaggedBool
	TextArray       *ra.ReadAccessFactsTaggedTextArray
	SymbolArray     *ra.ReadAccessFactsTaggedSymbolArray
	U64Array        *ra.ReadAccessFactsTaggedU64Array
}

func newAppStateReplyReader() *appStateReplyReader {
	return &appStateReplyReader{
		EntityId:        ra.NewReadAccessFactsPlainEntityIdAttributes(),
		EntityTimestamp: ra.NewReadAccessFactsPlainEntityTimestampAttributes(),
		Bool:            ra.NewReadAccessFactsTaggedBool(),
		TextArray:       ra.NewReadAccessFactsTaggedTextArray(),
		SymbolArray:     ra.NewReadAccessFactsTaggedSymbolArray(),
		U64Array:        ra.NewReadAccessFactsTaggedU64Array(),
	}
}

func (r *appStateReplyReader) loadFromRecord(rec arrow.Record) (err error) {
	err = r.EntityId.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("appstatereply: load EntityId: %w", err)
		return
	}
	err = r.EntityTimestamp.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("appstatereply: load EntityTimestamp: %w", err)
		return
	}
	err = r.Bool.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("appstatereply: load Bool: %w", err)
		return
	}
	err = r.TextArray.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("appstatereply: load TextArray: %w", err)
		return
	}
	err = r.SymbolArray.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("appstatereply: load SymbolArray: %w", err)
		return
	}
	err = r.U64Array.LoadFromRecord(rec)
	if err != nil {
		err = eh.Errorf("appstatereply: load U64Array: %w", err)
		return
	}
	return
}

func (r *appStateReplyReader) release() {
	if r == nil {
		return
	}
	if r.EntityId != nil {
		r.EntityId.Release()
	}
	if r.EntityTimestamp != nil {
		r.EntityTimestamp.Release()
	}
	if r.Bool != nil {
		r.Bool.Release()
	}
	if r.TextArray != nil {
		r.TextArray.Release()
	}
	if r.SymbolArray != nil {
		r.SymbolArray.Release()
	}
	if r.U64Array != nil {
		r.U64Array.Release()
	}
}

// Unmarshal appends one row to c per entity in rec, projecting
// the boxer.facts columns through factsschema/ra. Thin wrapper
// around AppStateReplyFillFromArrow — the per-row decode lives there.
func (c *AppStateReplyColumns) Unmarshal(rec arrow.Record) (err error) {
	r := newAppStateReplyReader()
	defer r.release()
	err = r.loadFromRecord(rec)
	if err != nil {
		return
	}
	n := r.EntityId.Len()
	err = AppStateReplyFillFromArrow(
		c,
		n,
		r.EntityId.ValueId,
		r.EntityId.ValueNaturalKey,
		r.EntityTimestamp.ValueTs,
		r.Bool.Attributes, r.Bool.Memberships,
		r.TextArray.Attributes, r.TextArray.Memberships,
		r.SymbolArray.Attributes, r.SymbolArray.Memberships,
		r.U64Array.Attributes, r.U64Array.Memberships,
	)
	return
}

// --- buscodec.CodecI bridge. ---

// AppStateReplyCodec is the buscodec.CodecI bridge for AppStateReply. Encodes one row
// through dml_cbor; decodes via cborarrow.Convert + ra-Unmarshal +
// Row(0). Auto-registered in init() so callers using buscodec.Encode
// / Decode route through here instead of the CBOR fallback.
type AppStateReplyCodec struct{}

var _ buscodec.CodecI = (*AppStateReplyCodec)(nil)

// appStateReplyBusCodec is the package-local singleton wired into buscodec.
var appStateReplyBusCodec = &AppStateReplyCodec{}

func (inst *AppStateReplyCodec) Name() (n string) {
	n = "appStateReply-sparse-cbor"
	return
}

func (inst *AppStateReplyCodec) ContentType() (ct string) {
	ct = "application/x-runtime-facts+rb;kind=appStateReply"
	return
}

func (inst *AppStateReplyCodec) Encode(v any) (b []byte, err error) {
	var row AppStateReply
	switch x := v.(type) {
	case AppStateReply:
		row = x
	case *AppStateReply:
		if x == nil {
			err = eh.Errorf("appstatereply: Encode nil *AppStateReply")
			return
		}
		row = *x
	default:
		err = eh.Errorf("appstatereply: Encode requires AppStateReply or *AppStateReply, got %T", v)
		return
	}
	cols := &AppStateReplyColumns{}
	cols.Append(row)
	var buf bytes.Buffer
	err = cols.Marshal(&buf)
	if err != nil {
		err = eh.Errorf("appstatereply: Encode marshal: %w", err)
		return
	}
	b = buf.Bytes()
	return
}

func (inst *AppStateReplyCodec) Decode(b []byte, v any) (err error) {
	target, ok := v.(*AppStateReply)
	if !ok {
		err = eh.Errorf("appstatereply: Decode requires *AppStateReply, got %T", v)
		return
	}
	var arrowBuf bytes.Buffer
	err = cborarrow.Convert(bytes.NewReader(b), &arrowBuf)
	if err != nil {
		err = eh.Errorf("appstatereply: Decode cborarrow: %w", err)
		return
	}
	rd, err := ipc.NewReader(&arrowBuf)
	if err != nil {
		err = eh.Errorf("appstatereply: Decode ipc reader: %w", err)
		return
	}
	defer rd.Release()
	if !rd.Next() {
		err = eh.Errorf("appstatereply: Decode expected one Arrow record, got none")
		return
	}
	rec := rd.RecordBatch()
	defer rec.Release()
	cols := &AppStateReplyColumns{}
	err = cols.Unmarshal(rec)
	if err != nil {
		err = eh.Errorf("appstatereply: Decode unmarshal: %w", err)
		return
	}
	if cols.Len() != 1 {
		err = eb.Build().Int("got", cols.Len()).Errorf("appstatereply: Decode expected 1 row")
		return
	}
	*target = cols.Row(0)
	return
}
